#!/usr/bin/env bash
# Builds nine of the ten component files from instructions/CLAUDE.md: one file per section, text unchanged.
# The tenth, components/HUMANIZE.md, is the original master prompt and is never generated or touched here.
# The card on top of each generated file quotes the source, and the build fails if a quote stops matching.
#
#   scripts/build-components.sh           write the files
#   scripts/build-components.sh --check   fail if any file differs from what would be written
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
SRC="$ROOT/instructions/CLAUDE.md"
MODE='write'
[ "${1:-}" = "--check" ] && MODE='check'

# file | card name | section heading in CLAUDE.md | tagline (an exact quote from that section)
TABLE='pacs.md|PACS|PACS — Petrus Agentic Coupling System|PACS marks those couplings so nothing is lost between sessions.
change-log.md|The Trace|.change-log.tsv (Machine Trace)|append one machine-only trace line
adversarial-analysis.md|Adversarial analysis|Changes To Working Systems — Adversarial Analysis MO|The goal is to never ship a change you have not tried to break yourself.
three-agent-sweep.md|Three-agent sweep|Three-Agent Sweep — Default For Debugging And Auditing|launch 3 parallel agents, each with a distinct lens or territory
debugging-discipline.md|Debugging discipline|Debugging Discipline|reproduce the USER'"'"'S EXACT symptom, not a proxy
git-hygiene.md|Git hygiene|Git Hygiene And Revert Safety|Use reversible history.
context-hygiene.md|Context hygiene|Context Hygiene And Fast Diagnostics|optimize for bounded context and fast answers.
tooling.md|Tooling|System Tooling Preferences|Prefer installed structured tools over broad raw output.
output-style.md|Output style|Output Style|Be ultra-token efficient, bordering on caveman, but with clear syntax.'

TARGET="$ROOT/components"
if [ "$MODE" = check ]; then
  TARGET="$(mktemp -d "${TMPDIR:-/tmp}/components.XXXXXX")"
  trap 'rm -rf "$TARGET"' EXIT
fi
mkdir -p "$TARGET"

printf '%s\n' "$TABLE" | while IFS='|' read -r file name heading tagline; do
  grep -qxF "## $heading" "$SRC" || { echo "section not found in CLAUDE.md: $heading" >&2; exit 1; }
  grep -qF -- "$tagline" "$SRC" || { echo "tagline is not a quote from CLAUDE.md: $tagline" >&2; exit 1; }
  {
    printf '<!-- Generated by scripts/build-components.sh from instructions/CLAUDE.md. Edit the source, not this file. -->\n\n'
    printf '> **%s** · *%s*\n' "$name" "$tagline"
    # shellcheck disable=SC2016
    printf '> From [`instructions/CLAUDE.md`](../instructions/CLAUDE.md), section "%s". [Back to the README](../README.md#the-components).\n\n---\n\n' "$heading"
    awk -v h="$heading" '
      $0 == "## " h { p = 1; print "# " h; next }
      p && /^## /   { exit }
      p             { lines[++n] = $0 }
      END { while (n > 0 && lines[n] == "") n--; for (i = 1; i <= n; i++) print lines[i] }
    ' "$SRC"
  } >"$TARGET/$file"
done

if [ "$MODE" = check ]; then
  status=0
  for f in "$TARGET"/*.md; do
    name="$(basename "$f")"
    cmp -s "$f" "$ROOT/components/$name" || { echo "out of sync: components/$name" >&2; status=1; }
  done
  [ -f "$ROOT/components/HUMANIZE.md" ] || { echo "missing: components/HUMANIZE.md" >&2; status=1; }
  if [ "$status" -ne 0 ]; then
    echo "Run scripts/build-components.sh and commit the result." >&2
    exit 1
  fi
  echo "components are in sync with their sources"
else
  echo "wrote $(printf '%s\n' "$TABLE" | wc -l | tr -d ' ') component files to components/"
fi
